blocks=[]
def add(text,style='NORMAL_TEXT',code=False):
    for p in text.strip().split('\n\n'):
        blocks.append({'text':p.strip()+'\n','style':style,'code':code})
def h(t):add(t,'HEADING_1')
def sub(t):add(t,'HEADING_2')

add('GameFrame Complete Technical Reference','TITLE')
add('Product, workflows, architecture, modeling, APIs, storage, operations and source-function catalog • 5 November 2026','SUBTITLE')
add('Audience: a technically curious collaborator or developer joining the project. Source: the current working checkout at C:\\Users\\Patrick\\source\\gameframe\\GameFrameJS. This is an implementation reference, not an accuracy certification or a public marketing specification. It includes proprietary implementation concepts because the requested audience is a friend receiving a full technical handoff. No credentials or saved player records are included.')
add('How to read: Chapters 1–12 explain the product and its design. Appendices A–G provide route registrations, database definitions, module/function indexes, configuration, tools/tests, and source fingerprints. Use the Google Docs outline to jump between modules. The function catalogs are a locator and dependency aid; signatures and listed calls are extracted from source rather than invented API promises.')
h('1. Product and feature map')
add('GameFrame extracts useful baseball measurements and timing comparisons from ordinary video. A hit can be measured for exit velocity (EV), launch angle, direction and modeled distance. A pitch can be tagged for travel time and estimated speed. A swing can be tagged for first movement, commitment and contact. Saved pitches and swings can then be aligned at contact to show when that hitter would need to start against that pitcher. These measurements are useful separately as well as together.')
add('The browser experience is guided: the app presents the next instruction, gathers a small piece of evidence, and advances. People do not need to remember the procedure. Automatic contact, field and ball suggestions reduce clicks, but require review and have manual alternatives. The application also includes saved-video management, team/hitter/pitcher management, dashboards, backups, onboarding, account/device/license handling and optional external-video import.')
sub('Home actions and screens')
add('Measure a hit for EV opens /ev/predictor.html. Create a matchup opens /matchup/select. Tag an existing swing opens the swing Library. Upload a new swing opens /multi-swing. Tag an existing pitch opens the pitch Library. Upload a new pitch opens /upload/pitch. Saved videos opens /library. Dashboard opens /dashboard/player. Team and player management open /teams and /hitters, with pitcher management also available. Many pages support embedded=1 and are presented inside the guided workspace rather than as independent browser navigation.')
add('Additional screens include measurement dashboards, pitch/swing/EV/matchup playback, pitch-speed review, pending clip tagging, batch pitch/swing selection, imported-video trimming, data backup/restore, account/login, getting started, privacy and terms. The HTML templates and their inline handlers are cataloged with the JavaScript modules below.')
sub('What the application does not establish')
add('A modeled EV is an inference from imperfect video and user input, not a radar reading. A good visual overlay alone does not prove a physically unique solution. Automatic ball and field detections can be wrong, especially with nets, blur, occlusion and camera motion. A source-code fit threshold or displayed range is not a statistically validated accuracy guarantee. The experimental tools and desktop packaging have different availability from a hosted deployment; those distinctions matter when demonstrating the product.')
h('2. System architecture and request flow')
add('The main service is Node.js/Express in server.js, with Nunjucks-rendered pages and better-sqlite3 storage. Browser JavaScript supplies the guided interface, exact-frame tagging, dialogs and progress displays. FFmpeg/FFprobe handle video metadata, frame extraction, trimming, cropping, compositing and exports. Python implements much of the EV modeling, source preparation and presentation rendering. Electron wraps the same local web service for the desktop application.')
add('The normal browser entry point is the main server, conventionally http://127.0.0.1:8000. npm start runs server.js; npm run start:all runs the launcher. The internal EV worker does not need a second public HTTP server. Historical clip_server.py retains HTTP-handler-shaped methods and a standalone development entry point, but ev-worker.js normally forwards relevant Express requests through a long-lived Python process.')
sub('Node-to-Python protocol')
add('createEvWorker selects GAMEFRAME_EV_PYTHON, then the checkout’s .venv-ev interpreter when available, then PYTHON or python. It supplies DB_PATH and FFmpeg paths. Each request is a JSON line containing id, method, original path, parsed body and a temporary response-file path. Python reconstructs a handler, writes response bytes to that file, and returns a JSON line containing id, status and headers. Node streams the file to the browser and removes the temporary response directory. Python logs go to stderr so stdout remains a protocol channel.')
add('The Python worker warms numerical imports, prediction code, media code and encoder capability checks before accepting work. A four-worker executor handles incoming requests. Prediction requests have cancellation registration; disconnecting /api/predict sends a CANCEL message. Node has a ten-minute worker watchdog, while some fallback subprocess paths have shorter per-operation timeouts. Killing a shared worker can reject other pending requests, so request cancellation and whole-worker termination have different consequences.')
sub('Dependencies and boundaries')
add('Production npm dependencies are Express, Nunjucks, better-sqlite3, Multer, ffmpeg-static and ffprobe-static. Electron and electron-builder are development/build dependencies. The Python requirements file pins NumPy, SciPy, OpenCV headless, Numba, llvmlite and Pillow. Optional vision/test paths can require additional assets or packages; a requirements file alone does not establish that every optional model is provisioned.')
add('The frontend uses local browser libraries including FFmpeg WASM assets, Leaflet and html2canvas. Cross-origin isolation headers support the browser media runtime. Satellite maps/geocoding, optional OpenAI pitch analysis, email delivery, hosted licensing and URL imports cross external-service boundaries. Local media processing is not a statement that every feature is offline.')
h('3. EV measurement: complete guided workflow')
sub('Selection, people and preloading')
add('The user selects a swing video and assigns the team and hitter early. The application remembers relevant upload selections and prepares source metadata/media while the user completes field information. Preparation must not wait for a typed description. Contact suggestions are hints, not the committed contact mark. Raw media preparation and fitted-result reuse are separate concerns: decoding or trimming a source early is legitimate preloading; presenting a stored fit as a fresh detection test is not.')
sub('Map, direction and landing')
add('The user enters a field address to locate the real map, identifies home plate and field orientation, places the camera, and marks the landing location. The map lets the user inspect distance and adjust the landing point before continuing. The field-location history is persisted and supports deletion. Map loading depends on external tile/geocoding availability and should expose a loading state rather than a blank page.')
add('Distance certainty is expressed as feet, not as a forced EV percentage: low certainty uses ±20 ft, medium ±10 ft and high ±5 ft. Low is the default. A broad landing allowance permits a range of landing distances; it does not require the inferred speed range to be broad when video evidence is stronger. A genuinely observed ground contact is different from a rough landing estimate and can support much tighter timing evidence.')
sub('Contact and source timing')
add('The user establishes the moment of bat/ball contact and clicks the contact point on the bat. Audio/motion suggestions can accelerate the search, but late or otherwise inconsistent suggestions must be corrected by the user. Whole-frame and between-frame timing are supported in relevant pickers. Original timestamps/frame identity matter, especially for variable frame rate, high frame rate and videos with playback-rate metadata. A universal fixed offset for every suggested contact would fix some clips and break others.')
sub('Automatic post-contact ball detection and review')
add('After contact is set, the integrated ball-assist path searches the actual source video. It uses the confirmed contact and video evidence, rather than a saved EV prediction, human flight marks or modeled candidate trajectory as a seed. The user reviews numbered detected positions over the contact image, aligned for estimated camera motion, and explicitly accepts them. Rejecting suggestions, canceling or a detection failure returns to ordinary interval tagging while retaining contact.')
add('The scan is sampled rather than evaluating every source frame. Source FPS determines a stride of at least five frames, approximately six samples per second in the wider scan, with denser early evidence and an up-to-ten-second search window. Sampled frames preserve original frame indices and timestamps. The detector continues through gaps rather than assuming the flight ended at a missing sample. A missing ball is not a license to invent an observation.')
add('The detector combines registered frame differences, contrast/blob candidates, tiled search coverage and multiple trajectory hypotheses. Reliable anchors can narrow the path and plausible distance between candidates. Bracket refinement investigates ambiguous intervals between independent anchors. Foreground nets, small balls, motion blur and camera pans remain difficult; the confidence and review UI are essential. Detection progress and model fitting progress are distinct operations.')
sub('Manual interval tagging and later flight')
add('The normal alternative asks for timed ball positions at guided intervals, with a Not visible option for each mark. Initial nominal-30-fps milestones include +10, +15 and +20 frames and then further intervals; 60-fps equivalents scale with source timing. After the initial required evidence, the user can move on to the rest of the process or keep adding observations. Skipped marks preserve missingness rather than creating fake coordinates.')
add('Early marks constrain the outgoing path and launch angle. Later marks can establish that the ball is still rising, near its apparent apex, or descending. Camera movement late in the clip must not force the fitted ball to follow the moved image coordinates as though the camera stayed fixed. Current default late evidence is timing-based; the separate descent-rate scoring implementation is disabled by default. See the modeling chapter for the exact distinction.')
sub('Automatic field suggestions and confirmation')
add('Field suggestions run on the contact reference frame using the contact/camera context and visible field evidence. White baseline markings are the intended line evidence. Home plate and two baseline directions constrain the field; if the pitching rubber is hidden, the code can propose an approximate mound-top reference using geometry and pitcher/mound context. That approximation must be treated as an approximation, not a visible rubber detection.')
add('Suggested markers remain pending until the user confirms them. They can be dragged, rejected or replaced with manual field tags. Two different clicks along the same actual baseline can be equally valid: their role is defining a line, not claiming those pixels are first or third base. Separated line points provide a more stable line estimate than bunched points. A marker near the plate is not an acceptable substitute for the mound.')
sub('Estimate, review and revision')
add('The prediction step builds an observation package and submits it to /api/predict. Review displays the best estimate, supported alternatives, model overlays and evidence/readiness messages. Editing landing, contact, flight positions or field setup must invalidate incompatible downstream results and rebuild from the updated inputs. The draft store and wizard state preserve work across revisions; Start over discards the draft through the appropriate workflow rather than silently leaving a stale saved draft.')
add('Dialogs are controlled through explicit buttons. modal-dismissal.js and guided dialog logic suppress unintended backdrop/Escape dismissal where applied. Nested EV/workspace presentation has dedicated handling to avoid multiple competing close layers. A technical-help link is a UI route, not a prediction API; it should not destroy the working measurement state.')
h('4. Camera geometry, flight modeling and estimate selection')
sub('Coordinate systems and calibration')
add('Map coordinates establish real-world field orientation, camera bearing and approximate distance. Field-image landmarks constrain camera projection. Image coordinates are pixels in a specified reference image, while modeled trajectories use real-world horizontal coordinates and vertical height with explicit unit conversions. The implementation contains both homography/plane utilities and full camera projection; a ground-plane mapping alone cannot reconstruct an airborne ball’s height.')
add('A camera map position is useful even after landmark tagging: it supplies a pose/bearing prior and helps resolve perspective/depth ambiguity. Landmark geometry refines what the camera sees. Camera height contributes to the projection and depth correction. The contact point remains on its observed camera ray rather than being forcibly located at home plate. The hit’s direction is needed to convert apparent image slope into a physical launch angle.')
add('A ball moving substantially away from the camera has compressed horizontal image motion. Its image path can therefore look steeper than its actual launch angle. The model projects candidate physical directions through the calibrated camera instead of treating raw pixel slope as launch angle. Near a directly-away view, angle/depth separation becomes poorly conditioned; direction, camera assumptions and user evidence matter more. A flat statement that launch angle is always precisely observable from any view would be incorrect.')
sub('Current staged policy')
add('The current staged fitter separates early geometry from later speed evidence. The early interval ends at approximately two-thirds of a second. Its spatial tangent/trajectory geometry is used to establish launch angle and spray direction without letting a landing-distance preference simply bend launch angle downward. Nominal geometry is then held while speed candidates are evaluated. There are explicitly limited-evidence fallback paths, so the fixed-angle policy should not be assumed for every diagnostic or legacy routine.')
add('Early camera-pan handling uses background registration under a level-camera/no-zoom assumption and adjusts horizontal position without treating late image height as trusted absolute height. Registration has evidence/trust checks. A substantial tilt, zoom, poor background match or changed view can violate the assumptions. The presence of a camera-motion field in JSON does not guarantee successful registration.')
add('Late flight evidence is primarily rise/apex/descent timing. The default staged_flight_match entry point has use_descent_rate=False. late_descent_rate.py can estimate relative vertical descent rate from sufficiently reliable registered sequences, but that optional path is not the default production policy. Absolute late horizontal or vertical image position must not drag an otherwise plausible early fit merely because the operator turned the camera.')
sub('Physics, candidates and ranking')
add('baseball_flight.py and flight_integrator.py simulate baseball motion, including the modeled aerodynamic/spin assumptions. Camera projection converts physical flight into predicted pixels at relevant times. Synthetic database tooling can generate, store and compare modeled hits. The active estimator also computes/refines candidates directly and uses caches; describing every estimate as a simple lookup of one prerecorded database row would be misleading.')
add('The staged speed search includes coarse candidates and finer refinement when reliable motion bounds permit it. Candidate records retain early projected-path residuals, timing consistency, distance and landing-direction checks, modeled speed, launch angle, spray/spin terms and trajectory metadata. Source code currently limits this staged search to a bounded speed domain, including a 40–120 mph range in the refinement path; behavior outside modeled domains should not be extrapolated casually.')
add('The best estimate is a ranked candidate under these model rules and the evidence supplied. Early path error, usable late timing, direction consistency and landing constraints contribute to eligibility/ranking. The ranking score is not a measured probability. A pixel RMS value summarizes image-space residuals; adding more points does not mechanically make RMS bigger, but systematic camera-motion errors or inaccurate marks can increase it. That is why evidence selection and late-mark policy matter more than simply increasing a global pixel threshold.')
add('A fit ignoring estimated distance is a diagnostic using another selection of the same evidence. A fit within a stated landing tolerance is a constrained inference. Neither is an independent validation of the map mark. If no model reconciles the evidence, the application should request review rather than present an unsupported short/slow alternative as proof that the user’s distance is wrong.')
sub('Ranges, sensitivity and provenance')
add('Sensitivity routines perturb inputs and compare plausible models. They are useful for spotting direction, distance, camera or timing dependence, but do not automatically produce calibrated statistical confidence intervals. The frontend also has working-range presentation logic that can show a tight band around the chosen match while retaining broader ambiguity in metadata. A narrow headline must not be interpreted as external accuracy validation or conceal a material ambiguity.')
add('Observations distinguish human tags from computer-vision suggestions and record review state. Reference-frame coordinates, timestamp uncertainty, pixel uncertainty, alignment/registration metadata and skipped/not-visible observations have different meanings. The most important reproducibility artifact is the observation package plus model output and source timing, not just the displayed EV number.')
add('Compatibility output names such as direct_launch_angle, legacy_camera_angle_diagnostic and direction_first_match remain in use. A legacy string mentioning late height can survive in metadata even when current behavior is timing-only. Read the governing policy fields and current staged implementation, not an old label, when interpreting a saved result.')
h('5. Saving hits, background video and swing handoff')
add('The normal workflow now saves the measurement before finishing the presentation video. Save hit commits the observation package, prediction, selected team/hitter, description and a retained source clip. The background render proceeds independently so the user can review the saved hit or continue into swing timing. Saving a measurement and having a finished downloadable presentation are separate milestones.')
add('A stable save_request_key and an immutable-input hash make a repeated save idempotent. A retry with the same request should not duplicate the hit, render job or timing source. Reusing the key with conflicting measurement content is rejected. The lifecycle is saving → queued → rendering → ready, with error and retry handling. Legacy saved videos without the new status can still be ready when a generated BLOB exists.')
add('background_ev.py uses a single background-render executor and an active-job set. A token/status-conditional database update claims and completes work. A deleted or superseded hit cannot be recreated by a late finishing renderer. On worker startup, interrupted saving/rendering jobs are requeued from persisted source and measurement data. If the original source is gone or changed, retained source bytes can restore a suitable render input.')
add('The browser can show the retained source clip and one metrics overlay while waiting. ev-video-ready.js polls the saved status, changes to the final export without interrupting active playback, and stops for completion, failure, deletion or dismissed views. Download becomes available once the generated video is ready; failure offers retry. The metrics overlay is hidden on the final rendered video so two captions are not stacked.')
add('A separate contact-anchored swing source is prepared for timing. The saved EV record links through pending_swing_clips/ev_swing_links into the normal swing-tagging process. The user should not have to reenter team/hitter/contact just because the same hit will be used in a matchup. Source preparation caches raw media work, not an old prediction used as new evidence.')
add('Rendering combines source replay, metrics, maps, modeled flight visualization and result sections. Section work can run in parallel with bounded encoder threads, then concatenate compatible outputs by stream copy. Background FFmpeg children use lower Windows scheduling priority; this changes responsiveness, not the chosen estimate. The older explicit /api/clip job/status/download route and synchronous-compatible save path remain for callers that need those contracts.')
h('6. Swing timing and optional movement analysis')
add('A new upload or saved pending swing enters a frame-based tagging workflow. The user crops when necessary, verifies contact, tags the commitment/decision point, and tags the player’s first movement. The first-move criterion is a coaching/tagging convention and must be applied consistently across that player’s clips. Start-to-contact and commitment-to-contact are computed from source frame timing and are best discussed in milliseconds.')
add('The final swing clip ends at contact. The stored decision frame is rebased into the trimmed clip, rather than left as an unrelated original-video frame index. Source FPS, frame count, crop, camera view and swing type accompany the record. Exact-frame image streams and ImageBitmap/canvas review reduce dependence on imprecise HTML video seeking.')
add('Optional pose processing is supported for appropriate side-hitter-chest views. Pose data and quality/reference features support dashboard comparison, but pose is not required for ordinary timing tags. The player dashboard can compare swings, flag a reference/best swing, filter swing types and delete records. A swing reference and a physical EV estimate are related through player/clip links, not interchangeable measurements.')
add('Batch swing import analyzes a longer source for candidate events, lets the user choose/split clips, and stores pending swings for later tagging. Candidate contact detection should not be described as completed timing analysis until the user has tagged or accepted the required events.')
h('7. Pitch measurement, source retention and batch workflows')
add('Pitch tagging establishes an endpoint slightly in front of the plate for the matchup timing convention, whether or not the actual pitch was hit. Release and endpoint frames determine travel time. Mound distance, extension and endpoint offset determine effective travel distance. The source FPS must represent the captured frames rather than an assumed universal rate.')
add('The manual speed calculation uses effectiveDistance = moundDistance − extension − contactDistance and elapsedFrames = contactFrame − releaseFrame. Average mph = 3600 × effectiveDistance × fps / (5280 × elapsedFrames). The manual displayed speed applies a 1.05 multiplier. Release selection can use adjacent frames and a half-frame choice. Inputs must be finite, distances physically valid and contact later than release.')
add('pitch-vision.js supplies optional frame-based release/endpoint assistance and a more detailed speed model with configurable velocity loss. Its correction is not numerically identical to the fixed manual 1.05 multiplier: with a 10% loss setting, 1/(1 − lossPercent/200) is approximately 1.05263. Speed metadata should retain the method and assumptions so a reader knows what the number means.')
add('Optional OpenAI analysis uses configured credentials/model settings and sends selected video imagery to that service. The pitch-release YOLO route is a separate test aid. Neither is the same algorithm as the EV ball tracker. Manual review remains available, including when the release point or endpoint cannot be identified reliably.')
add('Pitch sources are retained separately with hashed source identity and linked to saved clips. Cropped/tagged clips, source video, speed JSON and speed-annotated exports have different roles. The Library supports original-source access and pitch-speed download/export. A batch pitch import can propose event splits, create pending pitch clips, assign pitchers and finish measurement later.')
h('8. Matchups and presentation outputs')
add('A matchup combines a saved pitch and a fully tagged swing. server.js resolves contact in both clips, converts to a common output frame rate, and pads the swing with its first frame until the two contacts line up. The player’s first movement and commitment point then appear at specific moments in the pitch delivery. The coaching purpose is to learn when to start a consistent swing against different pitchers rather than merely rush the movement against faster velocity.')
add('The server-side compositor uses a 60-fps common timeline and inserts a two-second event freeze. The output presents the swing larger and the pitch as a smaller view. A two-panel start/decision collage uses a large swing image with a smaller pitch inset. Playback screens provide the video, collage/image and download controls together. Title/card formatting and visual geometry are media-export implementation details rather than measurement evidence.')
add('A saved matchup stores a video BLOB and associated thumbnail/collage plus a snapshot of pitch-speed metadata. Changing a source record later does not silently regenerate every prior exported matchup. Creating a matchup can involve usage authorization and completion reporting in licensed configurations. An uploaded finished matchup is a different path from generating one from source tags.')
add('GameFrame also contains offline demo, narration, caption, walkthrough and export-production scripts. They are developer/content-production utilities, not normal user-facing APIs or a live integration that automatically publishes to YouTube or Drive. Their filenames are listed in the tooling appendix so maintainers can locate them.')
h('9. Library, management, dashboards and persistence')
add('The Library organizes saved pitches, swings, EV hits and matchups, along with pending clips. It supports type filters, playback, editing descriptions, individual/bulk deletion, speed/media exports, original sources, finishing pending tags and starting matchups. Thumbnail routes and asynchronous preparation reduce repeated full-video work. A pending background EV video is still a saved measurement, with its status exposed to the Library.')
add('Teams, hitters and pitchers are distinct entities. Players have team relationships and descriptions. The upload flow can create people inline, and the app remembers relevant selections. Management deletion and Library deletion should be tested against linked records; a UI delete is not proof that every external source file or historical export is erased.')
add('The measurement dashboard summarizes EV and pitch data with time/player filters. The player dashboard focuses on swing timing, commitment-to-contact and optional pose/reference comparison. measurement-summary.js calculates finite-value statistics including count, mean, median, extrema and sample standard deviation. Small sample sizes and inconsistent tagging criteria limit what consistency charts can prove.')
add('app.db holds operational records, JSON measurement payloads and many media BLOBs. Retained source videos and temporary processing files also exist on disk. A database backup preserves BLOB-backed media, but a complete recovery plan must account for any externally stored source paths and required model/runtime assets. The schema appendix is a read-only snapshot of table/column/index definitions, not a copy of saved records.')
add('Desktop startup creates automatic database backups with retention; settings also expose manual backup/restore. Restore validates the database and requires appropriate application state/reload handling. Backups can contain player information, videos, account settings and local authentication tokens, so they should be handled as private application data.')
h('10. API conventions and important contracts')
add('These are same-origin application APIs, not a separately versioned public SDK. Page routes return HTML/redirects; media routes return binary streams; JSON endpoints are used by the guided UI. Upload endpoints use multipart data where configured. Express accepts large JSON/urlencoded bodies, and Multer has a configurable upload cap. Readiness, validation and not-found failures must be handled explicitly by callers.')
add('The route catalog includes Express USE registrations and regex handlers because middleware order and mounts affect actual behavior. USE is a mount/forwarding boundary, not a standalone HTTP verb. The Python handler catalog expands EV endpoints behind those mounts. Static direct-field extraction is not a complete formal schema: destructured/helper-read fields, dynamically constructed URLs and binary multipart parts need the owning implementation.')
sub('EV prediction and observations')
add('POST /api/predict accepts the observation package directly. It includes schema_version, video_metadata, hit/contact, camera/field/landmarks, distance_observation, ball_observations and optional terminal-event evidence. Contact and observations contain actual timing and coordinates with uncertainty/provenance. The server resolves the source, records diagnostic package/output files and invokes direct_video_estimate through the warm prediction runtime or fallback process. The response is the prediction JSON, including fit/readiness metadata and _live_prediction processing diagnostics. It is not just a scalar EV.')
add('POST /api/track and POST /api/landmarks are separate processing contracts; do not confuse /api/track with /api/ball-assist/track. POST /api/gameframe/video-timing retrieves timing preparation, and POST /api/gameframe/preload-contact starts contact-related preparation. GET/POST /api/gameframe/options and team/hitter endpoints bridge the EV screen to shared entity selections. /api/gameframe/field-locations manages saved map setups.')
sub('Saving and playback')
add('POST /api/gameframe/save-hit accepts package, prediction, selected hitter_id/team_id, description and save/export options. defer_video_render:true selects the save-first path; save_request_key supports safe repeat submission. Export-readiness blockers can return a review-required conflict. The successful deferred response reports the saved hit and measurement/video status, with pending timing links when available. Clients must not assume generated media is ready merely because the measurement was saved.')
add('GET /api/gameframe/ev-video-status?id=<hitId> reports saved render state. POST /api/gameframe/retry-ev-video with id requeues eligible failed media work. GET /play/ev?id= opens the normal playback page. GET /stream/ev-clip supports source/generated selection and inline delivery. The legacy /api/gameframe/ev-clip, /ev-hit, /ev-hits and /ev-json paths provide stored media/measurement access. POST /api/clip returns a job_id; status/download routes complete that separate render-job contract.')
sub('Ball-assist adapter')
add('The local ball-assist server defines /api/session, /api/session/:id/contact, source/frame retrieval, /api/detect, /api/track and job GET/DELETE routes. app-integration.cjs mounts it under /api/ball-assist with URL rewriting, so normal integrated callers use /api/ball-assist/session, /api/ball-assist/detect and /api/ball-assist/jobs/:id. The source catalog preserves original declarations so the adapter relationship is explicit. Session/job identifiers refer to detection work, not the saved EV hit ID.')
add('The adapter is deliberately gated by local-host/loopback and production settings. A tool working at localhost is not automatically available on a public hostname or in a packaged desktop build. The normal manual tagging alternative remains necessary when optional detection is missing or unavailable.')
sub('Upload, finalize, management and authentication')
add('Upload/finalize routes use temporary media identifiers plus player/team/crop/timing metadata. The swing finalize contract includes start_frame, decision_frame and contact_frame, source fps/frame_count, swing type/view and optional pose data. Pitch finalize stores its endpoint and clip/source associations. Batch analyze/split/pending routes are separate steps; a candidate split is not equivalent to a completed measurement.')
add('Library delete/update endpoints are POST actions, while metadata, raw frames and streaming are GETs. Stream handlers support byte ranges for seeking where implemented. The hosted auth/usage API is versioned under /api/v1, unlike the older application endpoints. It includes request/verify code, license status, device revoke, usage authorize/complete and admin usage/license actions. Credentials/tokens belong in the actual configured header/cookie flow; none are embedded in this reference.')
h('11. Desktop, hosted access, security and deployment')
add('Electron starts the application locally, uses its own user-data database and logs, and opens a browser window with contextIsolation enabled, nodeIntegration disabled and sandbox enabled. External web links open in the operating system browser. Desktop paths differ from the source-checkout app.db; a user seeing different data may have opened a different server/build/database rather than merely a different page.')
add('usage-auth.js implements email-code login, sessions, devices, trial/pass limits and usage accounting. Defaults include a short code expiry, attempt/rate limits, time-limited sessions, a small trial matchup allowance and admin-granted licenses. Usage authorization has request-level idempotency and completion/failure reporting. Payment-related columns do not establish a finished checkout/billing integration.')
add('The desktop gate checks local authentication state for protected navigation, but hosted account APIs do not by themselves make every Library route tenant-isolated. Core baseball tables are not universally owner-scoped. Before offering a multi-user hosted service, enforce server-side authorization and record ownership across every page, API and media route. This is an identified architectural boundary, not a claim of a completed security assessment.')
add('Protect diagnostic and administrative exposure: /debug/routes and /comparison_output/live can reveal implementation/measurement information; auth development-code mode must not be enabled in production; admin APIs need their configured secret. Local settings/backups may retain authentication material. Upload limits, external-video host validation, temporary-file handling, dependency updates and filesystem access all belong in deployment review.')
add('Dockerfile provides a Node/FFmpeg/Python-oriented base, but does not by itself install the complete scientific EV requirements. The Electron file manifest includes the main EV code but does not include experiments/ball-assist or a full Python environment simply because they exist in the checkout. Optional YOLO/model assets also need explicit provisioning. Treat hosted and packaged builds as separate acceptance targets, with manual fallback tested in each.')
add('The service worker favors fresh same-origin application HTML/JavaScript while caching selected heavy local assets. It is not a guarantee of full offline maps or authentication. Changes to service-worker cache versions, multiple running servers, browser caches and differing DB_PATH settings can all explain apparent old-version behavior. Use a visible build identifier plus the actual listening process/database path when troubleshooting.')
h('12. Performance, testing and operational handoff')
add('User-perceived time is the full journey: video choice → metadata/frame preparation → contact/field work → ball detection → fitting → saved measurement → completed export. A fast cached recalculate is not a benchmark of a fresh workflow. Record separate milestones and report both cold and warm results. Repeat tests must not use stored human marks, saved candidates or previous predictions as fresh automatic-detection input.')
add('Existing speed work includes early source preparation, exact sampled-frame transport, streaming decode, retained timing metadata, long-lived imported numerical/media code, encoder capability warmup, evidence/candidate caches, adaptive candidate refinement, bounded render parallelism and save-first background export. These improve different bottlenecks; none removes the need to profile the actual browser path on representative video.')
add('Recent local save-first evidence demonstrates that committing a measurement and reaching a source-playback/timing-ready state can finish in several seconds while the presentation continues. That is not an end-to-end detection/estimate guarantee: fresh auto-detection in loaded real-video runs still took on the order of a minute or more. Timings vary with source size, codec, frame rate, CPU load, network tiles and whether preparation is cold.')
add('npm test runs the Node test runner. Python checks and workflow scripts cover focused modeling/media behavior. The tooling appendix lists test/profile/replay scripts rather than treating them all as product endpoints. Some scripts access saved data, launch FFmpeg, create exports or modify records; inspect before execution. This documentation task did not run application tests, restart the server, change measurements or write production DB rows.')
add('Suggested maintenance sequence: establish a known source and source timing; capture a fresh observation package; confirm field/direction/contact evidence; measure each processing phase; compare deterministic model outputs; then run normal acceptance and manual-fallback browser flows, revision/recalculate, deletion, render retry/recovery and timing handoff. Separately validate desktop packaging and hosted permissions. Accuracy claims require held-out reference measurements, not just agreement with the same marks used to fit.')

h('Appendix A. Complete registered route catalog')
add('Source positions are relative to the canonical checkout. Entries preserve source registration order within files. Regex/dynamic mounts and USE are listed explicitly. Input names are direct static reads; “not directly enumerated” does not mean the endpoint accepts no fields. Refer to named helpers and the function catalog for indirect validation. Response keys are examples observed in handler code, not exhaustive schemas. A status absent from the list is not proof it cannot occur.')
for file,items in __import__('itertools').groupby(JS['routes'],key=lambda r:r['file']):
    sub(file)
    for r in items:
        add(f"{r['method']} {r['path']}  [{r['file']}:{r['line']}]\nInputs: {', '.join(r['inputs']) or 'not directly enumerated'}. Middleware/helpers: {', '.join(r['handlers']) or 'inline handler'}. Explicit statuses: {', '.join(map(str,r['statuses'])) or 'not statically enumerated'}. JSON keys: {', '.join(r['jsonKeys']) or 'HTML, binary, delegated or not statically enumerated'}.")
sub('EV Python handler endpoints behind the main-server mounts')
for r in PY['routes']:
    add(f"{r['method']} {r['path']}  [{r['file']}:{r['line']}]\nHandler: {r['handler']}. Direct fields: {', '.join(r['inputs']) or 'read in delegated helper/body parser'}. Standalone-only static asset handlers are not exposed by the normal worker GET allowlist.")

h('Appendix B. Operational database schema and indexes')
add('Schema snapshot only: no table rows were read for this reference. Defaults and declared constraints are copied as schema, not inferred behavior. SQLite declarations and enabled foreign-key enforcement are separate concerns. Source initialization/migrations can add columns to older databases. Synthetic modeling databases are separate from this operational DB.')
for t in SCHEMA:
    sub(t['table'])
    add(t['sql']+';',code=True)
    for i in t['indexes']:
        cols=', '.join(str(c['name']) for c in i['columns'])
        add(f"Index {i['name']}: {'UNIQUE ' if i['unique'] else ''}({cols}); origin={i['origin']}; partial={bool(i['partial'])}.")
    for f in t['foreign_keys']:add('Declared foreign key: '+json.dumps(f,separators=(',',':')),code=True)
sub('Synthetic/model database')
add('load_sqlite.py defines synthetic_hits (EV, launch/spray/spin, distance, hang/apex and landing truth), trajectory_points (time, position, velocity, speed, height) and generated comparison/projection tables in supporting tools. Base indexes include synthetic_hits(exit_velocity_mph, launch_angle_deg), distance_ft, hang_time_s and trajectory_points(hit_id, relative_time_s). A composite index beginning with EV is not equivalent to a dedicated launch-angle-first index for every query shape. Inspect query plans and actual active candidate-search code before claiming that an index speeds a particular estimate. Some rebuild/load scripts drop modeling tables; never run them against app.db.')

h('Appendix C. JavaScript module and function catalog')
add('Scope: first-party production browser/server/Electron code, inline template scripts, startup/build helpers and the integrated ball-assist runtime. Excludes third-party/vendor libraries, generated bundles, test assertions and one-off recording/report scripts. Named declarations, assigned functions, methods and identifiable event callbacks are indexed; anonymous iterator callbacks are represented by their containing function. Calls are a short static locator list, may include nested helpers and are not a complete call graph. Line ranges identify the current snapshot only.')
for f in JS['files']:
    sub(f['file'])
    funcs=[r for r in JS['functions'] if r['file']==f['file']]
    if not funcs:add('No named first-party JavaScript functions extracted; this file provides markup, declarations, module setup or anonymous handlers.')
    for fn in funcs:
        owner=(fn['owner']+'.') if fn['owner'] and fn['owner']!=fn['name'] else ''
        add(f"{'async ' if fn['async'] else ''}{owner}{fn['name']}{fn['signature']}  [lines {fn['line']}–{fn['endLine']}; {fn['kind']}]\nCalls: {', '.join(fn['calls']) or 'no direct calls extracted'}.",code=True)

h('Appendix D. Python module, class and function catalog')
add('Scope: EV runtime and synthetic/modeling modules, integrated ball-assist runtime and pitch-release YOLO helper. Offline comparison, generation, ablation and legacy fit modules are included for maintainers; their presence is not proof that the current normal workflow invokes them. Docstring summaries are copied from source and can lag policy changes; the current call path governs behavior.')
for f in PY['files']:
    sub(f['file'])
    if f.get('description'):add(f['description'])
    for cl in PY['classes']:
        if cl['file']==f['file']:add('Class: '+json.dumps({k:v for k,v in cl.items() if k!='file'},ensure_ascii=False),code=True)
    for fn in [r for r in PY['functions'] if r['file']==f['file']]:
        txt=f"{'async ' if fn['async'] else ''}{fn['name']}{fn['signature']}  [lines {fn['line']}–{fn['endLine']}]"
        if fn.get('description'):txt+='\n'+fn['description']
        txt+='\nCalls: '+(', '.join(fn['calls']) or 'no direct calls extracted')+'.'
        add(txt,code=True)

h('Appendix E. Environment configuration and CLI flags')
add('Names/default expressions below come from source. No environment values or secrets were inspected. These include internal flags and offline-tool options, not only deployment settings. Expression-based defaults must be evaluated in the owning code’s context. This is a configuration locator, not a recommended production .env file.')
envs=[]
for f in JS['files']:
    for m in re.finditer(r'process\.env\.([A-Z][A-Z0-9_]*)', (ROOT/f['file']).read_text(encoding='utf-8-sig')):
        line=(ROOT/f['file']).read_text(encoding='utf-8-sig')[:m.start()].count('\n')+1
        envs.append((m[1],f['file'],line))
for name in sorted(set(x[0] for x in envs)):
    refs=list(dict.fromkeys(f'{f}:{line}' for n,f,line in envs if n==name))
    add(name+' — '+', '.join(refs),code=True)
sub('Python environment reads')
for e in PY['environment']:add(f"{e['name']} — default expression: {e.get('default')}; {e['file']}:{e['line']}",code=True)
sub('Python command-line parameters')
for e in PY['cli']:add(f"{e['file']}:{e['line']} — {' / '.join(e['flags'])}; {json.dumps(e['options'],ensure_ascii=False)}",code=True)

h('Appendix F. Build, test and supporting tool registry')
add('Package commands: npm start / npm run dev (main server); npm run start:all (launcher); npm test (Node tests); npm run desktop (Electron); npm run build:desktop (staged desktop packaging). Use the checkout’s installed lockfile/dependencies and configured Python environment. Do not execute repair/rebuild/restore scripts just to inspect them.')
for directory in ['scripts','tests','test','experiments/ball-assist']:
    base=ROOT/directory
    if not base.exists():continue
    sub(directory)
    candidates=sorted(p for p in base.rglob('*') if p.is_file() and p.suffix in {'.js','.cjs','.py','.json','.md'} and not any(x in p.parts for x in ['node_modules','__pycache__','output','sessions','.venv','models','artifacts']))
    for p in candidates:
        if len(p.relative_to(base).parts)>2:continue
        add(str(p.relative_to(ROOT)).replace('\\','/'),code=True)

h('Appendix G. Source fingerprint manifest and scope')
add(f"Inventory includes {len(JS['files'])} JavaScript/template/build files with {len(JS['functions'])} named function/callback entries, {len(PY['files'])} Python files with {len(PY['functions'])} function entries, {len(JS['routes'])} Express registrations, {len(PY['routes'])} Python handler routes and {len(SCHEMA)} operational SQLite tables. Counts include nested functions and mounted middleware; they are not counts of public product features. AST parse errors: JavaScript {len(JS['errors'])}, Python {len(PY['errors'])}.")
add('This checkout contains ongoing uncommitted work. Hashes below identify the actual files read, rather than implying a released Git revision. The reference does not include vendor source, every anonymous callback, generated media, secret values, player records or exhaustive prose documentation of one-off demo scripts. The tool registry locates those scripts. Public HTTP contract stability and scientific accuracy require separate validation.')
for f in JS['files']+PY['files']:add(f"{f['file']} — {f['lines']} lines — SHA-256 {f['sha256']}",code=True)
add('End of technical reference. Use current source and migrations when behavior changes after this snapshot.')

# Keep connector payloads modest; all chunks append in original order.
chunks=[];chunk=[];size=0
for b in blocks:
    if size+len(b['text'])>18000 and chunk:chunks.append(chunk);chunk=[];size=0
    chunk.append(b);size+=len(b['text'])
if chunk:chunks.append(chunk)
for i,c in enumerate(chunks):(OUT/f'chunk-{i:03}.json').write_text(json.dumps(c,ensure_ascii=True),encoding='utf-8')
manifest={'chunks':len(chunks),'paragraphs':len(blocks),'characters':sum(len(b['text']) for b in blocks),'words':sum(len(b['text'].split()) for b in blocks),'js_functions':len(JS['functions']),'py_functions':len(PY['functions'])}
(OUT/'document-manifest.json').write_text(json.dumps(manifest,indent=2))
(OUT/'reference.txt').write_text(''.join(b['text'] for b in blocks),encoding='utf-8')
print(json.dumps(manifest))
